-- ═══════════════════════════════════════════════════════════════════════════
-- Seed — readiness_question_sets em STAGING (paridade com produção)
--
-- Gerado a partir das 40 linhas de produção (ndlsxgsccyjspbhzccyp).
-- Os `id` são os MESMOS de produção de propósito: mantém os dois bancos
-- comparáveis linha a linha.
--
-- Contexto: staging estava com a tabela VAZIA, então o QuestionSetsParser caía
-- em `getFallbackSet()` e servia sempre o mesmo set hardcoded ("O Clínico
-- (Padrão)"), com a rotação e a exclusão por usuário inertes. Não é bug da R.0
-- — é lacuna de paridade — mas trava qualquer teste do quiz em staging, e a R.2
-- precisa dos 40 sets para a 6ª pergunta de dor.
--
-- NÃO precisa redeploy: `getQuestionSetForUser` consulta a tabela a cada
-- request; o preload em memória só alimenta o caminho de fallback.
--
-- ⚠️ SÓ STAGING (gcaozgnevvmnlxnkfthh).
-- ═══════════════════════════════════════════════════════════════════════════

ON CONFLICT (set_number) DO NOTHING;

-- Verificação: tem que devolver 40, com set_number de 1 a 40 e 5 perguntas cada.
SELECT count(*) AS total,
       min(set_number) AS menor,
       max(set_number) AS maior,
       count(*) FILTER (WHERE jsonb_array_length(questions) <> 5) AS sets_fora_de_5,
       CASE WHEN count(*) = 40
             AND count(*) FILTER (WHERE jsonb_array_length(questions) <> 5) = 0
            THEN '✅' ELSE '❌' END AS veredito
  FROM public.readiness_question_sets;
